INSERT INTO trechos (id, texto, publico, macronarrativa, pauta, tipo, forca, link, pagina) VALUES ('D06-TR-146-fam', '“São eles que discutem a pauta. São eles que aprovam e desaprovam. Então a nossa vida passa na mão dos deputados.”', 'jovens', 'família e cuidado', 'comunicação e linguagem', 'verbatim', NULL, NULL, '40'), ('D06-TR-148-fam', '“As pessoas votam para senador, para deputado, mas não sabem o que fazem. Acham que o importante é só o presidente e o governador.”', 'jovens', 'família e cuidado', 'comunicação e linguagem', 'verbatim', NULL, NULL, '40'), ('D06-TR-149-fam', '“Seria interessante se ensinassem na escola a atribuição de cada um.”', 'jovens', 'família e cuidado', 'comunicação e linguagem', 'verbatim', NULL, NULL, '40'), ('D01-TR-084-jov', 'O vínculo mais seguro com o país nasce do cotidiano: família, comida, humor, cuidado, território, com o orgulho regional (nordestino/baiano) como camada extra de identidade.', 'jovens', 'brasil e pertencimento', 'orgulho e identidade nacional', 'achado', 'indício', NULL, '31'), ('D01-TR-131', 'O pertencimento nacional não aparece principalmente por símbolos oficiais, mas por cultura, comida, Bahia, Carnaval, povo, reconhecimento externo e orgulho de uma identidade popular.', 'jovens', 'brasil e pertencimento', 'orgulho e identidade nacional', 'achado', 'indício', NULL, '50'), ('D03-TR-070-jov', 'A defesa do Brasil no exterior recebe 24,8% de avaliação ótima ou boa e 34,5% ruim ou péssima, com 15,2% sem saber avaliar, a maior taxa de não avaliação entre as áreas.', 'jovens', 'brasil e pertencimento', 'soberania e política externa', 'achado', 'indício', NULL, '73'), ('D03-TR-071-jov', 'A proteção ao meio ambiente na gestão federal recebe 23,2% de avaliação ótima ou boa e 37,8% ruim ou péssima.', 'jovens', 'brasil e pertencimento', 'clima', 'achado', 'indício', NULL, '73'), ('D03-TR-087-jov', 'O Programa Brasil Soberano é o menos conhecido da lista (15,9%); a avaliação registrada é 35,5% ótima ou boa, 14,8% ruim ou péssima e 22,2% não sabem avaliar.', 'jovens', 'brasil e pertencimento', 'soberania e política externa', 'achado', 'indício', NULL, '76'), ('D04-TR-068-bra', 'O repertório digital jovem traduz crítica social por humor, trend e experiência concreta, mais do que por explicação institucional longa.', 'jovens', 'brasil e pertencimento', 'comunicação e linguagem', 'achado', 'indício', NULL, '19'), ('D04-TR-197-bra', 'A força das macronarrativas está em transformar pressão cotidiana em informação, proteção e horizonte possível.', 'jovens', 'brasil e pertencimento', 'comunicação e linguagem', 'achado', 'indício', NULL, '40'), ('D06-TR-081', 'Brasil Core tem aderência quando fala de cultura, comida, Carnaval, Bahia, povo, orgulho e soberania, e perde força quando soa propaganda ou símbolo vazio. Potencial narrativo médio/alto, com potencial emocional, mas precisa ser aterrado em cultura vivida e proteção do Brasil real.', 'jovens', 'brasil e pertencimento', 'orgulho e identidade nacional', 'achado', 'indício', NULL, '32'), ('D06-TR-115', 'O Brasil mobiliza quando aparece como cultura vivida, não como propaganda patriótica.', 'jovens', 'brasil e pertencimento', 'orgulho e identidade nacional', 'achado', 'indício', NULL, '37'), ('D06-TR-141-bra', 'Explicar quem decide transforma desconfiança em possibilidade de cobrança.', 'jovens', 'brasil e pertencimento', 'comunicação e linguagem', 'achado', 'indício', NULL, '40'), ('D06-TR-143-bra', 'Há uma lacuna clara: muitos sabem que política importa, mas não necessariamente sabem onde cada decisão acontece.', 'jovens', 'brasil e pertencimento', 'comunicação e linguagem', 'achado', 'indício', NULL, '40'), ('D07-TR-002-jov', 'A defesa do país no exterior aparece entre as três áreas de maior peso na avaliação pública de desempenho governamental, acima de áreas de serviço de uso direto.', 'jovens', 'brasil e pertencimento', 'soberania e política externa', 'achado', 'indício', NULL, '3'), ('D07-TR-005-jov', 'Proteção ao meio ambiente tem peso muito baixo na formação da avaliação pública de desempenho governamental.', 'jovens', 'brasil e pertencimento', 'clima', 'achado', 'indício', NULL, '3'), ('D07-TR-024-jov', 'Defesa do Brasil no exterior consta na lista de temas cuja menção deve ser evitada no momento.', 'jovens', 'brasil e pertencimento', 'soberania e política externa', 'achado', 'indício', NULL, '5'), ('D07-TR-032-jov', 'Na Região Sudeste, a defesa do país no exterior é a área de maior peso na avaliação de desempenho governamental, à frente de custo de vida.', 'jovens', 'brasil e pertencimento', 'soberania e política externa', 'achado', 'indício', NULL, '7'), ('D07-TR-034-jov', 'Na Região Sudeste, proteção ao meio ambiente tem peso na avaliação cerca do dobro do observado no conjunto do país, ainda que em patamar baixo.', 'jovens', 'brasil e pertencimento', 'clima', 'achado', 'indício', NULL, '7'), ('D07-TR-037-jov', 'Na Região Centro-Oeste, proteção ao meio ambiente ocupa a quarta posição em peso na avaliação, contraste marcado com a última posição no conjunto do país.', 'jovens', 'brasil e pertencimento', 'clima', 'achado', 'indício', NULL, '8'), ('D07-TR-038-jov', 'Na Região Centro-Oeste, a defesa do país no exterior ocupa posição de peso mais baixa na avaliação do que no conjunto do país.', 'jovens', 'brasil e pertencimento', 'soberania e política externa', 'achado', 'indício', NULL, '8'), ('D07-TR-042-jov', 'Na Região Nordeste, a defesa do país no exterior ocupa posição de peso muito mais baixa na avaliação do que no conjunto do país.', 'jovens', 'brasil e pertencimento', 'soberania e política externa', 'achado', 'indício', NULL, '9'), ('D01-TR-085', 'O estigma do "jeitinho brasileiro" justificando desonestidade é ponto de desconforto na identidade nacional.', 'jovens', 'brasil e pertencimento', 'orgulho e identidade nacional', 'afasta', NULL, NULL, '32'), ('D01-TR-086-jov', 'A associação do brasileiro a "preguiçoso" é rejeitada com força.', 'jovens', 'brasil e pertencimento', 'orgulho e identidade nacional', 'afasta', NULL, NULL, '32'), ('D01-TR-133', 'O território do pertencimento nacional perde força quando se aproxima de propaganda, verde-amarelo genérico ou nacionalismo sem consequência prática.', 'jovens', 'brasil e pertencimento', 'orgulho e identidade nacional', 'afasta', NULL, NULL, '50'), ('D04-TR-228-bra', 'Infantilizar afasta: esses jovens podem ter trabalho, família e filhos, e precisam ser reconhecidos como jovens sem serem tratados como adolescentes.', 'jovens', 'brasil e pertencimento', 'condição juvenil', 'afasta', NULL, NULL, '40'), ('D04-TR-229-bra', 'Cobrar que o jovem resolva sozinho o que é estrutural afasta: ele precisa de informação simples, proteção efetiva e caminhos claros.', 'jovens', 'brasil e pertencimento', 'autonomia e amparo', 'afasta', NULL, NULL, '40'), ('D04-TR-230-bra', 'Convocação abstrata afasta: a comunicação precisa começar nos temas que já organizam a rotina, estudo, transporte, consumo, primeiro emprego, escala, família e segurança.', 'jovens', 'brasil e pertencimento', 'comunicação e linguagem', 'afasta', NULL, NULL, '40'), ('D06-TR-118', 'O território de Brasil Soberano perde força quando se aproxima de propaganda, verde-amarelo genérico ou nacionalismo sem consequência prática.', 'jovens', 'brasil e pertencimento', 'orgulho e identidade nacional', 'afasta', NULL, NULL, '37'), ('D06-TR-162-bra', 'Falar com um "jovem" abstrato afasta: este público se mede por responsabilidade, tempo curto, dinheiro, família e futuro, e precisa ser tratado como jovem adulto.', 'jovens', 'brasil e pertencimento', 'comunicação e linguagem', 'afasta', NULL, NULL, '10'), ('D06-TR-163-bra', 'Reproduzir estereótipos de jovem irresponsável, geração que não quer trabalhar ou gente sem experiência para opinar afasta: a juventude vira marca de suspeita e gera irritação.', 'jovens', 'brasil e pertencimento', 'etarismo', 'afasta', NULL, NULL, '11'), ('D06-TR-165-bra', 'Mensagens sobre futuro que soam apenas inspiracionais afastam: futuro crível mostra caminho, condição e proteção.', 'jovens', 'brasil e pertencimento', 'futuro possível', 'afasta', NULL, NULL, '13'), ('D06-TR-167-bra', 'Reduzir a comunicação com jovens a "linguagem jovem" afasta: o que aproxima é reconhecer uma juventude encurtada por trabalho, família, medo e necessidade de construir futuro cedo.', 'jovens', 'brasil e pertencimento', 'comunicação e linguagem', 'afasta', NULL, NULL, '15'), ('D01-TR-132', 'O território do pertencimento nacional ganha força quando fala de um Brasil vivido: acarajé, cultura, música, Nordeste, periferia, trabalho, alegria e resistência.', 'jovens', 'brasil e pertencimento', 'orgulho e identidade nacional', 'funciona', NULL, NULL, '50'), ('D04-TR-018-bra', 'O conteúdo aproxima mais quando vem em formato curto e real: relato, bastidor, tutorial, comparação, antes e depois e dica prática.', 'jovens', 'brasil e pertencimento', 'comunicação e linguagem', 'funciona', NULL, NULL, '10'), ('D04-TR-048-bra', 'Relatos, tutoriais, bastidores, antes e depois e linguagem direta aproximam mais do que propaganda.', 'jovens', 'brasil e pertencimento', 'comunicação e linguagem', 'funciona', NULL, NULL, '14'), ('D04-TR-190-bra', 'Comunicar com concretude, linguagem simples, prova verificável e formatos próximos: relato, bastidor, tutorial, antes e depois, humor e checagem.', 'jovens', 'brasil e pertencimento', 'comunicação e linguagem', 'funciona', NULL, NULL, '39'), ('D04-TR-199-bra', 'Transformar políticas em condição de vida melhor: dinheiro, trabalho e engajamento precisam aparecer como suporte concreto, como pagar o básico, sair da dívida, trabalhar com dignidade, entender direitos, checar informações e cobrar resultados.', 'jovens', 'brasil e pertencimento', 'comunicação e linguagem', 'funciona', NULL, NULL, '40'), ('D04-TR-200-bra', 'Partir da vida real, não da convocação abstrata: a comunicação deve começar nos temas que já organizam a rotina, como estudo, transporte, consumo, primeiro emprego, escala, Pix, taxa das blusinhas, família, segurança, voto e futuro.', 'jovens', 'brasil e pertencimento', 'comunicação e linguagem', 'funciona', NULL, NULL, '40'), ('D04-TR-201-bra', 'Dar competência sem transferir responsabilidade: o jovem não precisa ser cobrado a resolver sozinho o que é estrutural, e sim de informação simples, proteção efetiva e caminhos claros para viver melhor, decidir com mais segurança e voltar a vislumbrar futuro.', 'jovens', 'brasil e pertencimento', 'comunicação e linguagem', 'funciona', NULL, NULL, '40'), ('D06-TR-003-bra', 'As narrativas de maior força são as que partem da vida concreta.', 'jovens', 'brasil e pertencimento', 'comunicação e linguagem', 'funciona', NULL, NULL, '7'), ('D06-TR-117', 'O território de Brasil Soberano ganha força quando fala de um Brasil que eles vivem: acarajé, cultura, música, Nordeste, periferia, trabalho, alegria e resistência.', 'jovens', 'brasil e pertencimento', 'orgulho e identidade nacional', 'funciona', NULL, NULL, '37'), ('D06-TR-142-bra', 'Responsabilização é menos um território emocional e mais uma chave de tradução: ganha força quando explica por que o voto para Legislativo, Senado e Congresso afeta salário, escala, direitos, internet, transporte, segurança e programas.', 'jovens', 'brasil e pertencimento', 'comunicação e linguagem', 'funciona', NULL, NULL, '40'), ('D06-TR-144-bra', 'Quando a comunicação traduz quem aprova, quem bloqueia, quem executa e quem responde, a política deixa de parecer um bloco distante.', 'jovens', 'brasil e pertencimento', 'comunicação e linguagem', 'funciona', NULL, NULL, '40'), ('D06-TR-155-bra', 'Proteção do trabalhador, dinheiro no bolso e proteção da família são os territórios de maior lastro espontâneo — já estão na vida dos jovens antes da política aparecer, por isso devem funcionar como portas de entrada principais.', 'jovens', 'brasil e pertencimento', 'comunicação e linguagem', 'funciona', NULL, NULL, '42'), ('D06-TR-156-bra', 'Brasil Core e Engajamento Cívico têm potencial, mas precisam de prova: Brasil precisa aparecer como cultura vivida e soberania concreta; Engajamento precisa mostrar onde a voz jovem produz efeito.', 'jovens', 'brasil e pertencimento', 'comunicação e linguagem', 'funciona', NULL, NULL, '42'), ('D06-TR-158-bra', 'Responsabilização e Senado é a principal ponte pedagógica: não mobiliza sozinho, mas ajuda a transformar temas concretos em escolha eleitoral, mostrando quem aprova, quem trava, quem amplia e quem ameaça.', 'jovens', 'brasil e pertencimento', 'comunicação e linguagem', 'funciona', NULL, NULL, '42'), ('D01-TR-081-jov', '"O Pix é nosso, o SUS pode ser melhor, e o Brasil presta"', 'jovens', 'brasil e pertencimento', 'orgulho e identidade nacional', 'verbatim', NULL, NULL, '30'), ('D06-TR-055', '“Eu tenho essa preocupação constante de não conseguir chegar onde eu quero.”', 'jovens', 'brasil e pertencimento', 'futuro possível', 'verbatim', NULL, NULL, '13'), ('D06-TR-056', '“A nossa maior preocupação acaba sendo realmente o futuro. O que eu vou ser amanhã?”', 'jovens', 'brasil e pertencimento', 'futuro possível', 'verbatim', NULL, NULL, '13'), ('D06-TR-057', '“A preocupação sempre existe, porque eu acho que o amanhã é muito imprevisível.”', 'jovens', 'brasil e pertencimento', 'futuro possível', 'verbatim', NULL, NULL, '13'), ('D06-TR-120', '“Acho que nossa cultura é muito forte. A gente tem um background muito bonito. Hoje em dia, eu vejo o Brasil muito mais sendo propagado lá fora.”', 'jovens', 'brasil e pertencimento', 'orgulho e identidade nacional', 'verbatim', NULL, NULL, '37'), ('D06-TR-121', '“Quando eu estou comendo acarajé, em qualquer ponto aqui de Salvador, eu me sinto brasileira. O Carnaval, eu me sinto brasileira.”', 'jovens', 'brasil e pertencimento', 'orgulho e identidade nacional', 'verbatim', NULL, NULL, '37'), ('D06-TR-122', '“Os pessoal de fora estão querendo dar palpites aqui nas nossas eleições. Aqui quem manda aqui sou eu.”', 'jovens', 'brasil e pertencimento', 'orgulho e identidade nacional', 'verbatim', NULL, NULL, '37'), ('D06-TR-146-bra', '“São eles que discutem a pauta. São eles que aprovam e desaprovam. Então a nossa vida passa na mão dos deputados.”', 'jovens', 'brasil e pertencimento', 'comunicação e linguagem', 'verbatim', NULL, NULL, '40'), ('D06-TR-148-bra', '“As pessoas votam para senador, para deputado, mas não sabem o que fazem. Acham que o importante é só o presidente e o governador.”', 'jovens', 'brasil e pertencimento', 'comunicação e linguagem', 'verbatim', NULL, NULL, '40'), ('D06-TR-149-bra', '“Seria interessante se ensinassem na escola a atribuição de cada um.”', 'jovens', 'brasil e pertencimento', 'comunicação e linguagem', 'verbatim', NULL, NULL, '40'), ('D01-TR-027-jov', 'Há competência real de gestão cotidiana (casa, filhos, negócio e dinheiro), a mesma usada para avaliar quem cumpriu e quem só prometeu; não é preciso ensinar este público a pensar politicamente.', 'jovens', 'participação e voz', 'decisão de voto', 'achado', 'indício', NULL, '17'), ('D01-TR-105', 'Jovens são cobrados como adultos, mas desqualificados como jovens: um padrão forte é a irritação com estereótipos de jovem irresponsável, geração que não quer trabalhar, gente sem experiência ou sem propriedade para opinar.', 'jovens', 'participação e voz', 'juventude e trabalho', 'achado', 'forte', NULL, '38'), ('D01-TR-106', 'O jovem não rejeita política, mas sim polarização, promessa, briga e teatro eleitoral: a conversa política circula mais dentro de casa ou entre pessoas com posições parecidas; fora desse círculo, falar de política vira risco de briga ou julgamento.', 'jovens', 'participação e voz', 'participação política', 'achado', 'indício', NULL, '38'), ('D01-TR-134', 'A política só ganha relevância quando encosta na régua de viabilidade: aliviar pressão, ampliar estabilidade, proteger quem importa e transformar planos em possibilidade real.', 'jovens', 'participação e voz', 'participação política', 'achado', 'indício', NULL, '51'), ('D01-TR-135', 'Pautas interessam, eleição cansa.', 'jovens', 'participação e voz', 'participação política', 'achado', 'indício', NULL, '52'), ('D01-TR-136', 'O jovem não rejeita política, mas sim polarização, promessa, briga e teatro eleitoral.', 'jovens', 'participação e voz', 'participação política', 'achado', 'indício', NULL, '52'), ('D01-TR-137', 'O voto importa, mas precisa deixar de parecer só obrigação.', 'jovens', 'participação e voz', 'decisão de voto', 'achado', 'indício', NULL, '53'), ('D01-TR-138', 'O voto é escolha, não necessariamente esperança.', 'jovens', 'participação e voz', 'decisão de voto', 'achado', 'indício', NULL, '53'), ('D01-TR-139', 'Indecisão não é ignorância: é um processo de avaliação em um cenário de baixa confiança.', 'jovens', 'participação e voz', 'decisão de voto', 'achado', 'indício', NULL, '53'), ('D01-TR-143-jov', 'O Legislativo é pouco compreendido, um grande ponto cego: perguntadas sobre o papel do Senado, as respostas variam entre acerto parcial, confusão com outros cargos e desconhecimento assumido sem constrangimento.', 'jovens', 'participação e voz', 'funcionamento do legislativo', 'achado', 'indício', NULL, '55'), ('D03-TR-013-jov', 'O WhatsApp é a rede de uso mais universal: 87,3% da população utiliza todos os dias e apenas 7,2% nunca ou quase nunca utiliza.', 'jovens', 'participação e voz', 'informação e desinformação', 'achado', 'indício', NULL, '20'), ('D03-TR-058', 'Em 2025, entre jovens de 16 e 17 anos que ainda não tiraram o título de eleitor, 94,2% pretendiam tirar o documento e votar nas eleições de 2026.', 'jovens', 'participação e voz', 'decisão de voto', 'achado', 'indício', NULL, '51'), ('D03-TR-104-jov', 'Família e fé são apontados como os valores que mais mobilizam o voto.', 'jovens', 'participação e voz', 'decisão de voto', 'achado', 'indício', NULL, '97'), ('D04-TR-003', 'A diferença geracional não está necessariamente em "querer curtir", mas em estar construindo autonomia, identidade, repertório de decisão e trajetória em um momento da vida que ainda é de formação.', 'jovens', 'participação e voz', 'condição juvenil', 'achado', 'indício', NULL, '7'), ('D04-TR-010', 'Na macronarrativa participação e voz, a narrativa central para o público jovem vai do jovem como alvo da disputa ao jovem como sujeito competente da escolha.', 'jovens', 'participação e voz', 'participação política', 'achado', 'indício', NULL, '8'), ('D04-TR-011', 'O engajamento deixa de ser cobrança para virar competência cívica: entender, checar, comparar, escolher, participar e cobrar a partir da própria vida.', 'jovens', 'participação e voz', 'participação política', 'achado', 'indício', NULL, '8'), ('D04-TR-014', 'A vida já cobra o jovem como adulto, mas ele ainda está formando trajetória, autonomia e repertório de decisão.', 'jovens', 'participação e voz', 'condição juvenil', 'achado', 'indício', NULL, '10'), ('D04-TR-019', 'As redes sociais ativam comparação e ansiedade no público jovem.', 'jovens', 'participação e voz', 'informação e desinformação', 'achado', 'indício', NULL, '10'), ('D04-TR-068-par', 'O repertório digital jovem traduz crítica social por humor, trend e experiência concreta, mais do que por explicação institucional longa.', 'jovens', 'participação e voz', 'comunicação e linguagem', 'achado', 'indício', NULL, '19'), ('D04-TR-124', 'Para o público jovem, participar não é escolher um lado o tempo todo: é conseguir decidir sem virar alvo da disputa.', 'jovens', 'participação e voz', 'participação política', 'achado', 'indício', NULL, '29'), ('D04-TR-125', 'O jovem não deve ser lido como apático: ele avalia a política a partir de efeitos concretos sobre trabalho, dinheiro, família, segurança e futuro.', 'jovens', 'participação e voz', 'decisão de voto', 'achado', 'indício', NULL, '29'), ('D04-TR-126', 'Muitos jovens já carregam responsabilidades adultas, mas ainda estão formando repertório político e critérios de escolha.', 'jovens', 'participação e voz', 'participação política', 'achado', 'indício', NULL, '29'), ('D04-TR-129', 'A representação importa quando o jovem sente que sua realidade, identidade ou causa aparece na política.', 'jovens', 'participação e voz', 'representação política', 'achado', 'indício', NULL, '29'), ('D04-TR-130', 'A política aparece misturada ao feed: entretenimento, meme, trend, cultura pop, futebol, checagem e opinião circulam juntos.', 'jovens', 'participação e voz', 'informação e desinformação', 'achado', 'indício', NULL, '29'), ('D04-TR-132', 'O digital estimula a expressão, mas também a ansiedade de exposição; não se posicionar pode aparecer como forma de evitar conflito.', 'jovens', 'participação e voz', 'polarização', 'achado', 'indício', NULL, '29'), ('D04-TR-134', 'Na escuta digital, o participação e voz aparece mais ligado à política institucional, a lideranças e ao debate nacional do que à vida cotidiana local.', 'jovens', 'participação e voz', 'participação política', 'achado', 'indício', NULL, '29'), ('D04-TR-135', 'Há consciência da importância do voto, mas também forte disputa sobre primeiro voto, voto adolescente e posicionamento ideológico.', 'jovens', 'participação e voz', 'decisão de voto', 'achado', 'indício', NULL, '29'), ('D04-TR-136', 'A polarização é gatilho de engajamento, mas também produz lógica de "eu contra eles", segregação e medo de se indispor.', 'jovens', 'participação e voz', 'polarização', 'achado', 'indício', NULL, '29'), ('D04-TR-137', 'Representação, pertencimento e orgulho do voto aparecem com força na escuta digital; ao mesmo tempo, conquistas tendem a ser atribuídas a líderes mais do que ao protagonismo coletivo.', 'jovens', 'participação e voz', 'representação política', 'achado', 'indício', NULL, '29'), ('D04-TR-142', 'A macronarrativa participação e voz organiza a tensão entre participação como pertencimento e participação como exposição ao conflito.', 'jovens', 'participação e voz', 'participação política', 'achado', 'indício', NULL, '30'), ('D04-TR-143', '"Participação sob pressão" é isotopia reiterada: o jovem sabe que o voto importa, mas participar pode significar se expor, tomar lado e entrar em conflito.', 'jovens', 'participação e voz', 'participação política', 'achado', 'forte', NULL, '30'), ('D04-TR-144', '"Política como identidade e pertencimento" é isotopia reiterada: o engajamento aparece ligado a representação, orgulho do voto e identificação com lideranças, causas ou coletivos.', 'jovens', 'participação e voz', 'representação política', 'achado', 'forte', NULL, '30'), ('D04-TR-145', '"Polarização e risco de segregação" é isotopia reiterada: a política mobiliza, mas também divide o mundo em "nós contra eles", reduzindo quem discorda a inimigo ou ignorante.', 'jovens', 'participação e voz', 'polarização', 'achado', 'forte', NULL, '30'), ('D04-TR-146', '"Vida real como critério de escolha" é isotopia reiterada: quando a política entra no cotidiano, ela ganha concretude e deixa de ser apenas disputa de líder ou partido.', 'jovens', 'participação e voz', 'decisão de voto', 'achado', 'forte', NULL, '30'), ('D04-TR-147', '"Informação, checagem e autonomia" é isotopia reiterada: o jovem circula entre meme, opinião, notícia e desinformação, e engajar também é aprender a verificar antes de aderir.', 'jovens', 'participação e voz', 'informação e desinformação', 'achado', 'forte', NULL, '30'), ('D04-TR-148', 'Primeiro voto, voto adolescente, obrigação de não ficar alienado, medo de se indispor, ansiedade de posicionamento e disputa ideológica estruturam as narrativas sobre participação.', 'jovens', 'participação e voz', 'decisão de voto', 'achado', 'indício', NULL, '30'), ('D04-TR-149', 'Representatividade, orgulho de ter escolhido certo, coletivos jovens, causas de gênero, defesa de direitos e sentimento de pertencer a um lado ou grupo estruturam as narrativas de identidade política.', 'jovens', 'participação e voz', 'representação política', 'achado', 'indício', NULL, '30'), ('D04-TR-150', 'A oposição entre campos ideológicos estrutura narrativas de briga entre lados, com acusação de burrice, preconceito, alienação, idolatria política e rejeição a quem pensa diferente.', 'jovens', 'participação e voz', 'polarização', 'achado', 'indício', NULL, '30'), ('D04-TR-151', 'Trabalho, dinheiro, educação, consumo, segurança, taxa das blusinhas, Pix, direitos, estudo, família e futuro funcionam como critérios para avaliar candidatos e políticas.', 'jovens', 'participação e voz', 'decisão de voto', 'achado', 'indício', NULL, '30'), ('D04-TR-152', 'Checagem, exposição de fake news, comparação de versões, busca por fontes, conteúdo explicativo e esforço para construir critério próprio estruturam as narrativas de informação.', 'jovens', 'participação e voz', 'informação e desinformação', 'achado', 'indício', NULL, '30'), ('D04-TR-159', 'O jovem é chamado a votar, tomar lado, não ficar alienado e se posicionar, mas essa convocação muitas vezes chega como pressão externa: líderes, campos ideológicos, grupos, memes e conflitos disputam sua adesão.', 'jovens', 'participação e voz', 'participação política', 'achado', 'indício', NULL, '31'), ('D04-TR-160', 'O objeto de valor é o repertório para conduzir o próprio percurso: entender o problema, checar informação, avaliar consequências, reconhecer o que afeta a própria vida, escolher com autonomia e cobrar resultado.', 'jovens', 'participação e voz', 'participação política', 'achado', 'indício', NULL, '31'), ('D04-TR-161', 'No estado final da transformação, o jovem deixa de ser apenas público-alvo da disputa e passa a ser sujeito da narrativa: interpreta, decide, participa quando faz sentido, defende pautas concretas e transforma o voto em instrumento do próprio projeto de vida.', 'jovens', 'participação e voz', 'participação política', 'achado', 'indício', NULL, '31'), ('D04-TR-162', 'Engajar não é performar posição o tempo todo: é construir critério, reconhecer o que muda na vida real e participar sem perder autonomia.', 'jovens', 'participação e voz', 'participação política', 'achado', 'indício', NULL, '31'), ('D04-TR-163', 'A transformação necessária é fazer com que o jovem deixe de ser apenas destinatário da mensagem política e passe a ocupar o lugar de sujeito da ação; o voto, a checagem, a conversa, a cobrança e a defesa de pautas concretas tornam-se modalidades do seu poder fazer.', 'jovens', 'participação e voz', 'participação política', 'achado', 'indício', NULL, '32'), ('D04-TR-165', 'O jovem se informa no fluxo do feed, entre meme, opinião, entretenimento, notícia e desinformação; ao mesmo tempo, é pressionado a se posicionar e ainda está formando repertório político.', 'jovens', 'participação e voz', 'informação e desinformação', 'achado', 'indício', NULL, '33'), ('D04-TR-167', 'Para o jovem, a política ganha sentido quando toca trabalho, dinheiro, consumo, estudo, segurança, família, gênero, direitos e futuro; temas como taxa das blusinhas, Pix, escala 6x1 e primeiro voto mostram essa entrada concreta.', 'jovens', 'participação e voz', 'decisão de voto', 'achado', 'indício', NULL, '33'), ('D04-TR-169', 'O digital estimula a expressão, mas também exposição, julgamento, briga e ansiedade; não se posicionar pode funcionar como autoproteção diante do conflito no feed, na família ou nos grupos.', 'jovens', 'participação e voz', 'polarização', 'achado', 'indício', NULL, '33'), ('D04-TR-171', 'A representação importa, mas o engajamento não pode ficar restrito ao orgulho do voto, à gratidão ao eleito ou à defesa de uma liderança.', 'jovens', 'participação e voz', 'representação política', 'achado', 'indício', NULL, '33'), ('D04-TR-174', 'Na narrativa da escolha com critério, o jovem é sujeito em formação de repertório político: recebe política pelo feed, cruza meme, opinião, notícia e desinformação, sente pressão para se posicionar, mas busca critérios para escolher com autonomia.', 'jovens', 'participação e voz', 'participação política', 'achado', 'indício', NULL, '34'), ('D04-TR-176', 'Transformação narrativa em jogo: no estado inicial, o jovem é atravessado por excesso de informação, cortes, memes, polarização e pressão para escolher um lado antes de entender plenamente o que está em jogo; a comunicação organiza o ruído, traduz o tema, mostra consequências concretas, oferece caminhos de checagem e legitima o tempo de formação de critério; no estado final, o jovem escolhe com mais autonomia: vota, compara propostas, identifica manipulação, compartilha informação segura e participa sem ser capturado pela polarização.', 'jovens', 'participação e voz', 'decisão de voto', 'achado', 'indício', NULL, '34'), ('D04-TR-178', 'Na narrativa da vida real como ponto de partida, o jovem é sujeito que interpreta a política pela consequência prática: percebe quando uma decisão afeta preço, renda, oportunidade, circulação, respeito, acesso e planos de vida.', 'jovens', 'participação e voz', 'decisão de voto', 'achado', 'indício', NULL, '35'), ('D04-TR-180', 'Transformação narrativa em jogo: no estado inicial, a política aparece como disputa distante entre líderes, partidos, cortes, memes e brigas nacionais, sem conexão clara com a rotina; a comunicação traduz a política em efeitos concretos, mostrando quem decide, o que muda, quem ganha, quem perde e como isso chega na vida do jovem; no estado final, o jovem reconhece que participar é entender como decisões públicas afetam sua vida e usar esse critério para escolher, votar e cobrar.', 'jovens', 'participação e voz', 'decisão de voto', 'achado', 'indício', NULL, '35'), ('D04-TR-182', 'Na narrativa da participação sem exposição, o jovem é sujeito que administra visibilidade: informa-se, observa, avalia riscos, escolhe quando falar, quando votar, quando compartilhar e quando evitar uma briga que não leva a lugar concreto.', 'jovens', 'participação e voz', 'participação política', 'achado', 'indício', NULL, '36'), ('D04-TR-184', 'Transformação narrativa em jogo: no estado inicial, a participação aparece como exposição, em que escolher lado, comentar, postar ou discutir pode gerar ansiedade, julgamento, conflito familiar, briga em grupo ou ataque no feed; a comunicação desloca o engajamento de performance pública para prática possível, em que cada jovem participa a partir do seu nível de segurança, repertório e disposição; no estado final, o jovem reconhece que pode participar sem se tornar alvo permanente da disputa: vota, informa-se, conversa, apoia e cobra com mais autonomia e menos pressão de exposição.', 'jovens', 'participação e voz', 'polarização', 'achado', 'indício', NULL, '36'), ('D04-TR-186', 'Na narrativa da cobrança de resultados, o jovem é sujeito que reconhece quem o representa, mas não delega totalmente sua voz: escolhe, acompanha, questiona, cobra entrega e entende conquistas como resultado também da participação coletiva.', 'jovens', 'participação e voz', 'representação política', 'achado', 'indício', NULL, '37'), ('D04-TR-188', 'Transformação narrativa em jogo: no estado inicial, o jovem pode se engajar pela identificação com líderes, causas ou campos políticos, mas corre o risco de ocupar um lugar passivo, de torcer, defender, agradecer ou apenas repostar; a comunicação desloca a representação de adesão para corresponsabilidade, com voto, apoio, cobrança, fiscalização e apropriação das conquistas; no estado final, o jovem se reconhece como protagonista do próprio programa cívico: não só representado, mas participante ativo da escolha, da pauta e da cobrança por resultado.', 'jovens', 'participação e voz', 'representação política', 'achado', 'indício', NULL, '37'), ('D04-TR-193', 'A política chega ao jovem misturada a feed, meme, corte, desinformação, entretenimento, família, trabalho e consumo.', 'jovens', 'participação e voz', 'informação e desinformação', 'achado', 'indício', NULL, '39'), ('D04-TR-194', 'A mobilização não nasce de dever moral, mas da percepção de consequência prática.', 'jovens', 'participação e voz', 'participação política', 'achado', 'indício', NULL, '39'), ('D04-TR-195', 'O sujeito desta análise não parte da apatia, mas de uma vida jovem já atravessada por responsabilidades.', 'jovens', 'participação e voz', 'condição juvenil', 'achado', 'indício', NULL, '40'), ('D04-TR-197-par', 'A força das macronarrativas está em transformar pressão cotidiana em informação, proteção e horizonte possível.', 'jovens', 'participação e voz', 'comunicação e linguagem', 'achado', 'indício', NULL, '40'), ('D06-TR-002', 'A escuta política parte de uma vida que já pesa, enquanto repertório, projetos e expectativas sobre o que pode ou não mudar ainda estão em formação.', 'jovens', 'participação e voz', 'condição juvenil', 'achado', 'indício', NULL, '7'), ('D06-TR-082', 'Engajamento cívico: "jovem tem poder" divide — pode soar frase vazia, mas ganha força quando vira ação concreta, rua, cobrança, informação e voto com consequência. Potencial narrativo médio, condicionado à prova; precisa mostrar como a voz vira efeito, não apenas convocar autoestima.', 'jovens', 'participação e voz', 'participação política', 'achado', 'forte', NULL, '32'), ('D06-TR-084', 'Há confusão institucional sobre cargos e responsabilização, mas existe interesse quando a explicação conecta deputados, Senado e leis a salário, escala de trabalho, transporte, internet e direitos. Potencial narrativo alto como tradução, não como tema isolado; potente para tirar a política da abstração.', 'jovens', 'participação e voz', 'comunicação e linguagem', 'achado', 'forte', NULL, '32'), ('D06-TR-126-2', 'Homens tendem a valorizar informação, pesquisa e decisão racional, mas desconfiam da política como ambiente.', 'jovens', 'participação e voz', 'participação política', 'achado', 'indício', NULL, NULL), ('D06-TR-134', 'Comparar passado e presente significa reconhecer que ganhou mais responsabilidade, mais oportunidades, mais capacidade de construir, mais consciência e mais custo de vida.', 'jovens', 'participação e voz', 'promessa e entrega', 'achado', 'indício', NULL, '39'), ('D06-TR-135', 'Para os jovens, o antes e depois mais imediato não é apenas governo A versus governo B: é adolescência versus vida adulta, dependência versus responsabilidade, promessa versus conta, sonho versus necessidade de construir. Isso combina com a tese da juventude interrompida.', 'jovens', 'participação e voz', 'promessa e entrega', 'achado', 'indício', NULL, '39'), ('D06-TR-141-par', 'Explicar quem decide transforma desconfiança em possibilidade de cobrança.', 'jovens', 'participação e voz', 'comunicação e linguagem', 'achado', 'indício', NULL, '40'), ('D06-TR-143-par', 'Há uma lacuna clara: muitos sabem que política importa, mas não necessariamente sabem onde cada decisão acontece.', 'jovens', 'participação e voz', 'comunicação e linguagem', 'achado', 'indício', NULL, '40'), ('D06-TR-150', 'Política só importa quando protege o que a vida já está cobrando: os territórios mais potentes não são os mais "políticos", mas os que organizam a experiência cotidiana.', 'jovens', 'participação e voz', 'comunicação e linguagem', 'achado', 'indício', NULL, '41'), ('D06-TR-151', 'O voto não é uma ideia abstrata de participação, mas uma escolha sobre tempo, dinheiro, segurança, direitos, família e futuro.', 'jovens', 'participação e voz', 'comunicação e linguagem', 'achado', 'forte', NULL, '41'), ('D07-TR-020-jov', 'Os temas de maior impacto são identificados como os preditores do voto, positivos para a situação e negativos para a oposição.', 'jovens', 'participação e voz', 'comunicação e linguagem', 'achado', 'indício', NULL, '1'), ('D13-TR-188', 'A crença na educação política pessoal como caminho é mais forte entre as participantes mais jovens.', 'jovens', 'participação e voz', 'informação sobre direitos', 'achado', 'indício', NULL, NULL), ('D04-TR-128', 'A política afasta quando vem como promessa abstrata, julgamento moral ou obrigação de posicionamento.', 'jovens', 'participação e voz', 'participação política', 'afasta', NULL, NULL, '29'), ('D04-TR-217', 'Reduzir participação a briga partidária afasta: engajamento precisa se aproximar do que o jovem já vive, voto, consumo, estudo, trabalho, direitos e futuro.', 'jovens', 'participação e voz', 'polarização', 'afasta', NULL, NULL, '29'), ('D04-TR-218', 'Apresentar engajamento como cobrança afasta: ele funciona como aprendizado de decisão, entender, comparar, checar, escolher e participar no próprio tempo.', 'jovens', 'participação e voz', 'participação política', 'afasta', NULL, NULL, '29'), ('D04-TR-219', 'Tratar o jovem como apático ou alienado afasta: ele avalia política pelos efeitos concretos sobre trabalho, dinheiro, família, segurança e futuro.', 'jovens', 'participação e voz', 'competência e autoestima política', 'afasta', NULL, NULL, '29'), ('D04-TR-220', 'Mensagens de "nós contra eles" afastam: a polarização reduz quem discorda a inimigo e gera medo de se indispor.', 'jovens', 'participação e voz', 'polarização', 'afasta', NULL, NULL, '30'), ('D04-TR-221', 'Convocar a votar, tomar lado ou "não ficar alienado" em tom de pressão externa afasta: a convocação chega como cobrança de líderes, campos e grupos.', 'jovens', 'participação e voz', 'participação política', 'afasta', NULL, NULL, '31'), ('D04-TR-222', 'Exigir que o jovem performe posição política o tempo todo para ser considerado consciente afasta: participar também envolve risco de exposição e conflito.', 'jovens', 'participação e voz', 'participação política', 'afasta', NULL, NULL, '36'), ('D04-TR-223', 'Restringir engajamento ao orgulho do voto, à gratidão ao eleito ou à defesa de uma liderança afasta: representação precisa virar acompanhamento e cobrança.', 'jovens', 'participação e voz', 'representação política', 'afasta', NULL, NULL, '37'), ('D04-TR-224', 'Tom professoral ou moralizante afasta: a linguagem precisa ser simples, curta e verificável, explicando o que está em jogo e onde checar.', 'jovens', 'participação e voz', 'comunicação e linguagem', 'afasta', NULL, NULL, '34'), ('D04-TR-225', 'Empurrar o jovem para um lado afasta: ele quer ser reconhecido como alguém capaz de entender, checar, comparar e decidir.', 'jovens', 'participação e voz', 'competência e autoestima política', 'afasta', NULL, NULL, '34'), ('D04-TR-226', 'Falar de política como disputa distante entre líderes, partidos, cortes e memes, sem conexão com a rotina, afasta.', 'jovens', 'participação e voz', 'participação política', 'afasta', NULL, NULL, '35'), ('D04-TR-227', 'Apelar ao dever moral não mobiliza: a mobilização nasce da percepção de consequência prática.', 'jovens', 'participação e voz', 'decisão de voto', 'afasta', NULL, NULL, '39'), ('D04-TR-228-par', 'Infantilizar afasta: esses jovens podem ter trabalho, família e filhos, e precisam ser reconhecidos como jovens sem serem tratados como adolescentes.', 'jovens', 'participação e voz', 'condição juvenil', 'afasta', NULL, NULL, '40'), ('D04-TR-229-par', 'Cobrar que o jovem resolva sozinho o que é estrutural afasta: ele precisa de informação simples, proteção efetiva e caminhos claros.', 'jovens', 'participação e voz', 'autonomia e amparo', 'afasta', NULL, NULL, '40'), ('D04-TR-230-par', 'Convocação abstrata afasta: a comunicação precisa começar nos temas que já organizam a rotina, estudo, transporte, consumo, primeiro emprego, escala, família e segurança.', 'jovens', 'participação e voz', 'comunicação e linguagem', 'afasta', NULL, NULL, '40'), ('D06-TR-022', 'Falar apenas de sonho, energia ou protagonismo jovem pode soar distante.', 'jovens', 'participação e voz', 'comunicação e linguagem', 'afasta', NULL, NULL, '11'), ('D06-TR-032', 'Tom professoral, moralizante ou condescendente tende a afastar.', 'jovens', 'participação e voz', 'comunicação e linguagem', 'afasta', NULL, NULL, '11'), ('D06-TR-124', 'O território é promissor, mas instável: a ideia de que jovens têm poder encontra desejo de reconhecimento, mas também descrença. Quando aparece como frase solta, pode soar vazia.', 'jovens', 'participação e voz', 'participação política', 'afasta', NULL, NULL, '38'), ('D06-TR-160', 'Apresentar o voto como dever moral afasta: o voto mobiliza quando aparece como consequência útil, verificável e ligada à vida que se está construindo.', 'jovens', 'participação e voz', 'decisão de voto', 'afasta', NULL, NULL, '7'), ('D06-TR-161', 'Pedir esperança, participação ou voto antes de reconhecer esforço, cansaço e pressão afasta um público que chega cansado.', 'jovens', 'participação e voz', 'participação política', 'afasta', NULL, NULL, '10'), ('D06-TR-162-par', 'Falar com um "jovem" abstrato afasta: este público se mede por responsabilidade, tempo curto, dinheiro, família e futuro, e precisa ser tratado como jovem adulto.', 'jovens', 'participação e voz', 'comunicação e linguagem', 'afasta', NULL, NULL, '10'), ('D06-TR-163-par', 'Reproduzir estereótipos de jovem irresponsável, geração que não quer trabalhar ou gente sem experiência para opinar afasta: a juventude vira marca de suspeita e gera irritação.', 'jovens', 'participação e voz', 'etarismo', 'afasta', NULL, NULL, '11'), ('D06-TR-164', 'Exigir atenção, engajamento ou participação sem respeitar um público que chega cansado afasta: a mensagem precisa ser direta, concreta e imediatamente reconhecível.', 'jovens', 'participação e voz', 'participação política', 'afasta', NULL, NULL, '11'), ('D06-TR-165-par', 'Mensagens sobre futuro que soam apenas inspiracionais afastam: futuro crível mostra caminho, condição e proteção.', 'jovens', 'participação e voz', 'futuro possível', 'afasta', NULL, NULL, '13'), ('D06-TR-167-par', 'Reduzir a comunicação com jovens a "linguagem jovem" afasta: o que aproxima é reconhecer uma juventude encurtada por trabalho, família, medo e necessidade de construir futuro cedo.', 'jovens', 'participação e voz', 'comunicação e linguagem', 'afasta', NULL, NULL, '15'), ('D01-TR-001-jov', 'Cerca de 4 milhões de eleitores permanecem indecisos para 2026.', 'jovens', 'participação e voz', 'decisão de voto', 'contexto', NULL, NULL, '6'), ('D01-TR-004-jov', 'Entre os votos em aberto, 53% correspondem a mulheres, 32% a jovens de 16 a 34 anos e 23% a pessoas 60+.', 'jovens', 'participação e voz', 'decisão de voto', 'contexto', NULL, NULL, '8'), ('D01-TR-007-jov', '81% dos eleitores do estado de São Paulo não têm escolha definida para o Senado.', 'jovens', 'participação e voz', 'decisão de voto', 'contexto', NULL, NULL, '8'), ('D01-TR-012-jov', 'Mulheres representam 52,84% do eleitorado, mais de 83,8 milhões de eleitoras.', 'jovens', 'participação e voz', 'decisão de voto', 'contexto', NULL, NULL, '13'), ('D01-TR-015-jov', 'O voto feminino costuma ser decidido nas semanas finais da campanha, com avaliação por critérios práticos de estabilidade familiar e considerando toda a comunidade, não apenas a própria pessoa.', 'jovens', 'participação e voz', 'decisão de voto', 'contexto', NULL, NULL, '13'), ('D01-TR-100', 'Jovens votam menos e confiam menos na democracia como melhor regime: apenas 42% dos jovens de 16 a 29 anos, contra 47% dos adultos de 30+.', 'jovens', 'participação e voz', 'confiança nas instituições', 'contexto', NULL, NULL, '37'), ('D01-TR-101-jov', 'O eleitorado de 16 a 18 anos encolheu 14,5% desde 2022, justamente o grupo que deveria estar entrando no jogo eleitoral.', 'jovens', 'participação e voz', 'decisão de voto', 'contexto', NULL, NULL, '37'), ('D01-TR-107', 'Reconhecer esforço, cansaço e pressão antes de pedir esperança, participação ou voto.', 'jovens', 'participação e voz', 'participação política', 'funciona', NULL, NULL, '38'), ('D01-TR-140', 'O voto tem potência, mas não se sustenta como chamado moral: precisa aparecer como escolha com consequência concreta — quem protege, quem ameaça, quem entrega, quem bloqueia e o que muda na vida depois da eleição.', 'jovens', 'participação e voz', 'decisão de voto', 'funciona', NULL, NULL, '53'), ('D01-TR-141', '"Jovem tem poder" só funciona quando mostra onde esse poder age.', 'jovens', 'participação e voz', 'participação política', 'funciona', NULL, NULL, '54'), ('D01-TR-142', 'Valorizar a capacidade de avaliação dos jovens sem infantilizá-los: o tom não deve ser "vocês são o futuro", mas "vocês já vivem as consequências e sabem reconhecer o que pesa".', 'jovens', 'participação e voz', 'participação política', 'funciona', NULL, NULL, '54'), ('D01-TR-144-jov', 'Quando a pergunta sobre o Senado é reformulada de forma concreta, associando-o a salário, escala de trabalho e direitos, o tom muda de indiferença para indignação.', 'jovens', 'participação e voz', 'funcionamento do legislativo', 'funciona', NULL, NULL, '55'), ('D01-TR-147-jov', 'A comunicação sobre o Legislativo não precisa começar pelo Senado, precisa começar pelo problema: escala 6x1, salário, transporte, segurança e segurança digital.', 'jovens', 'participação e voz', 'funcionamento do legislativo', 'funciona', NULL, NULL, '55'), ('D04-TR-012', 'A comunicação sobre engajamento precisa dar repertório sem tutelar: aproximar a política da vida real, reduzir ruído, evitar moralização e mostrar formas graduais de participação.', 'jovens', 'participação e voz', 'participação política', 'funciona', NULL, NULL, '8'), ('D04-TR-018-par', 'O conteúdo aproxima mais quando vem em formato curto e real: relato, bastidor, tutorial, comparação, antes e depois e dica prática.', 'jovens', 'participação e voz', 'comunicação e linguagem', 'funciona', NULL, NULL, '10'), ('D04-TR-048-par', 'Relatos, tutoriais, bastidores, antes e depois e linguagem direta aproximam mais do que propaganda.', 'jovens', 'participação e voz', 'comunicação e linguagem', 'funciona', NULL, NULL, '14'), ('D04-TR-127', 'A política mobiliza o jovem quando parece melhorar a vida.', 'jovens', 'participação e voz', 'participação política', 'funciona', NULL, NULL, '29'), ('D04-TR-131', 'Conteúdos curtos, relatos, memes e vídeos de identificação ajudam a traduzir política em linguagem reconhecível e compartilhável.', 'jovens', 'participação e voz', 'comunicação e linguagem', 'funciona', NULL, NULL, '29'), ('D04-TR-133', 'Cultura pop, pautas de gênero, memes, coletivos jovens e debates de consumo funcionam como portas de entrada para a política.', 'jovens', 'participação e voz', 'participação política', 'funciona', NULL, NULL, '29'), ('D04-TR-138', 'A narrativa precisa aproximar o engajamento da vida que o jovem já interpreta: voto, consumo, estudo, trabalho, direitos e futuro, sem reduzir a participação a briga partidária.', 'jovens', 'participação e voz', 'participação política', 'funciona', NULL, NULL, '29'), ('D04-TR-139', 'O engajamento deve ser apresentado como aprendizado de decisão, não como cobrança: entender, comparar, checar, escolher e participar no próprio tempo.', 'jovens', 'participação e voz', 'participação política', 'funciona', NULL, NULL, '29'), ('D04-TR-140', 'A comunicação precisa legitimar a autonomia do jovem: participar pode ser votar, buscar informação, discutir com cuidado, defender uma pauta ou não entrar em todo conflito.', 'jovens', 'participação e voz', 'participação política', 'funciona', NULL, NULL, '29'), ('D04-TR-141', 'A narrativa deve deslocar o jovem de espectador de lideranças para sujeito da escolha e da cobrança: quem vota, pauta, verifica, pressiona e se apropria das conquistas.', 'jovens', 'participação e voz', 'representação política', 'funciona', NULL, NULL, '29'), ('D04-TR-153', 'Figuras da participação sob pressão: título de eleitor, urna, consulta pública, cobranças para não ficar alienado, a pergunta sobre em quem votar, discussão no grupo, comentário no post e briga no feed.', 'jovens', 'participação e voz', 'participação política', 'funciona', NULL, NULL, '30'), ('D04-TR-154', 'Figuras do pertencimento político: expressões de vínculo pessoal com lideranças e com o país, sentimento de ser representado, coletivo jovem, meme de voto, camiseta, bandeira, post de apoio e liderança que fala por uma causa.', 'jovens', 'participação e voz', 'representação política', 'funciona', NULL, NULL, '30'), ('D04-TR-155', 'Figuras da polarização: lógica de "eu contra eles", referências a lideranças políticas nacionais e a instituições do Estado, print de discussão, vídeo de reação, deboche, cancelamento, comentário agressivo e unfollow.', 'jovens', 'participação e voz', 'polarização', 'funciona', NULL, NULL, '30'), ('D04-TR-156', 'Figuras da vida real como critério: Shein, blusinha, Pix, escola pública, ProUni, escala 6x1, fome, educação, preço, salário, benefício e "voto por quem passa por isso".', 'jovens', 'participação e voz', 'decisão de voto', 'funciona', NULL, NULL, '30'), ('D04-TR-157', 'Figuras da checagem: print, fact-checking, vídeo explicativo, portal de notícia, Google, YouTube, thread, creator político, "estudei o suficiente" e "não idolatro político".', 'jovens', 'participação e voz', 'informação e desinformação', 'funciona', NULL, NULL, '30'), ('D04-TR-158', 'O desafio é transformar o jovem de alvo da convocação política em sujeito competente da própria narrativa do voto.', 'jovens', 'participação e voz', 'participação política', 'funciona', NULL, NULL, '31'), ('D04-TR-164', 'participação e voz precisa transformar participação em competência: entender, escolher, cobrar e agir a partir da própria vida.', 'jovens', 'participação e voz', 'participação política', 'funciona', NULL, NULL, '33'), ('D04-TR-166', 'Mostrar que o engajamento começa antes do voto: entender o que está em jogo, checar informação, comparar propostas, reconhecer efeitos na própria vida e escolher com autonomia.', 'jovens', 'participação e voz', 'informação e desinformação', 'funciona', NULL, NULL, '33'), ('D04-TR-168', 'Aproximar a participação daquilo que o jovem já vive e interpreta: política não como teatro distante, mas como decisão que afeta preço, renda, oportunidade, circulação, respeito e projeto de vida.', 'jovens', 'participação e voz', 'decisão de voto', 'funciona', NULL, NULL, '33'), ('D04-TR-170', 'Legitimar formas graduais de participação: informar-se, conversar com cuidado, votar, apoiar uma causa, compartilhar algo checado ou cobrar resultado, sem exigir performance política permanente.', 'jovens', 'participação e voz', 'participação política', 'funciona', NULL, NULL, '33'), ('D04-TR-172', 'Deslocar o jovem de espectador representado para sujeito que acompanha, cobra e se apropria das conquistas: o sentimento de ser representado precisa virar também escolha, pauta e cobrança próprias.', 'jovens', 'participação e voz', 'representação política', 'funciona', NULL, NULL, '33'), ('D04-TR-173', 'participação e voz precisa transformar informação dispersa em competência de escolha: o jovem não deve ser empurrado para um lado, mas reconhecido como alguém capaz de entender, checar, comparar e decidir.', 'jovens', 'participação e voz', 'decisão de voto', 'funciona', NULL, NULL, '34'), ('D04-TR-175', 'Usar linguagem simples, curta e verificável: explicar o que está em jogo, quem decide, como afeta a vida real, onde checar e quais escolhas estão em disputa, sem tom professoral ou moralizante.', 'jovens', 'participação e voz', 'comunicação e linguagem', 'funciona', NULL, NULL, '34'), ('D04-TR-177', 'participação e voz ganha força quando deixa de parecer debate distante e mostra como decisões políticas atravessam a vida concreta do jovem: trabalho, dinheiro, consumo, estudo, segurança, família, gênero, direitos e futuro.', 'jovens', 'participação e voz', 'decisão de voto', 'funciona', NULL, NULL, '35'), ('D04-TR-179', 'Partir de cenas e temas reconhecíveis: taxa das blusinhas, Pix, escala 6x1, transporte, escola, faculdade, primeiro emprego, segurança, direitos e custo de vida.', 'jovens', 'participação e voz', 'decisão de voto', 'funciona', NULL, NULL, '35'), ('D04-TR-181', 'participação e voz precisa reconhecer que participar também envolve risco de exposição, julgamento e conflito; o jovem não deve ser cobrado a performar posição o tempo todo para ser considerado consciente.', 'jovens', 'participação e voz', 'polarização', 'funciona', NULL, NULL, '36'), ('D04-TR-183', 'Legitimar formas graduais de participação: checar, conversar com cuidado, votar, apoiar uma pauta, compartilhar informação segura, participar de coletivo ou cobrar resultado sem entrar em toda disputa do feed.', 'jovens', 'participação e voz', 'participação política', 'funciona', NULL, NULL, '36'), ('D04-TR-185', 'A representação importa, mas o engajamento não pode parar no orgulho do voto, na gratidão ao eleito ou na defesa de uma liderança; a narrativa precisa transformar identificação em acompanhamento, apropriação e cobrança.', 'jovens', 'participação e voz', 'representação política', 'funciona', NULL, NULL, '37'), ('D04-TR-187', 'Mostrar que o sentimento de ser representado precisa virar também pauta, escolha e cobrança próprias, valorizando lideranças sem apagar o protagonismo de quem vota, pressiona e sustenta causas.', 'jovens', 'participação e voz', 'representação política', 'funciona', NULL, NULL, '37'), ('D04-TR-189', 'Reconhecer o peso da vida real sem apagar a condição jovem: começo de trajetória, repertório em formação, busca por autonomia e desejo de planejar.', 'jovens', 'participação e voz', 'condição juvenil', 'funciona', NULL, NULL, '39'), ('D04-TR-190-par', 'Comunicar com concretude, linguagem simples, prova verificável e formatos próximos: relato, bastidor, tutorial, antes e depois, humor e checagem.', 'jovens', 'participação e voz', 'comunicação e linguagem', 'funciona', NULL, NULL, '39'), ('D04-TR-191', 'Mostrar o que muda na vida: dinheiro para seguir, trabalho com dignidade, voto com critério e participação sem exposição permanente.', 'jovens', 'participação e voz', 'comunicação e linguagem', 'funciona', NULL, NULL, '39'), ('D04-TR-199-par', 'Transformar políticas em condição de vida melhor: dinheiro, trabalho e engajamento precisam aparecer como suporte concreto, como pagar o básico, sair da dívida, trabalhar com dignidade, entender direitos, checar informações e cobrar resultados.', 'jovens', 'participação e voz', 'comunicação e linguagem', 'funciona', NULL, NULL, '40'), ('D04-TR-200-par', 'Partir da vida real, não da convocação abstrata: a comunicação deve começar nos temas que já organizam a rotina, como estudo, transporte, consumo, primeiro emprego, escala, Pix, taxa das blusinhas, família, segurança, voto e futuro.', 'jovens', 'participação e voz', 'comunicação e linguagem', 'funciona', NULL, NULL, '40'), ('D04-TR-201-par', 'Dar competência sem transferir responsabilidade: o jovem não precisa ser cobrado a resolver sozinho o que é estrutural, e sim de informação simples, proteção efetiva e caminhos claros para viver melhor, decidir com mais segurança e voltar a vislumbrar futuro.', 'jovens', 'participação e voz', 'comunicação e linguagem', 'funciona', NULL, NULL, '40'), ('D06-TR-003-par', 'As narrativas de maior força são as que partem da vida concreta.', 'jovens', 'participação e voz', 'comunicação e linguagem', 'funciona', NULL, NULL, '7'), ('D06-TR-008', 'Para mobilizar, a política precisa parecer útil, verificável e ligada à vida que ainda está sendo construída.', 'jovens', 'participação e voz', 'participação política', 'funciona', NULL, NULL, '7'), ('D06-TR-013', 'O desafio de comunicação não é apenas falar com jovens, mas com quem já vive responsabilidades adultas sem estabilidade plena, o que exige que a política pareça útil e conectada ao que está sendo construído.', 'jovens', 'participação e voz', 'participação política', 'funciona', NULL, NULL, '7'), ('D06-TR-016', 'A comunicação precisa reconhecer esforço, cansaço e pressão antes de pedir esperança, participação ou voto.', 'jovens', 'participação e voz', 'comunicação e linguagem', 'funciona', NULL, NULL, '10'), ('D06-TR-017', 'A comunicação precisa chegar à política pela vida real: rotina, trabalho, estudo, família, deslocamento, riscos e futuro aparecem antes de qualquer opinião eleitoral.', 'jovens', 'participação e voz', 'participação política', 'funciona', NULL, NULL, '10'), ('D06-TR-018', 'É no campo de pressão cotidiana que as mensagens políticas são recebidas.', 'jovens', 'participação e voz', 'participação política', 'funciona', NULL, NULL, '10'), ('D06-TR-027', 'Mensagens que exigem atenção, engajamento ou participação precisam respeitar um público que chega cansado.', 'jovens', 'participação e voz', 'jornada de trabalho', 'funciona', NULL, NULL, '11'), ('D06-TR-033', 'O melhor caminho é reconhecer experiência vivida, esforço e capacidade de avaliação.', 'jovens', 'participação e voz', 'comunicação e linguagem', 'funciona', NULL, NULL, '11'), ('D06-TR-076', 'Antes de pedir esperança, participação ou voto, é preciso mostrar que se entende o peso carregado por esse público.', 'jovens', 'participação e voz', 'comunicação e linguagem', 'funciona', NULL, NULL, '15'), ('D06-TR-125', 'Quando vem acompanhada de ação concreta, a ideia de que jovem tem poder ganha densidade: votar, cobrar, protestar, produzir conteúdo, informar a família, circular dados e ocupar espaços.', 'jovens', 'participação e voz', 'participação política', 'funciona', NULL, NULL, '38'), ('D06-TR-127', 'A narrativa precisa valorizar a capacidade de avaliação dos jovens sem infantilizá-los: o tom não deve ser "vocês são o futuro", mas "vocês já vivem as consequências e sabem reconhecer o que pesa".', 'jovens', 'participação e voz', 'comunicação e linguagem', 'funciona', NULL, NULL, '38'), ('D06-TR-132', 'Comparar passado e presente ajuda quando vira prova concreta, não bordão eleitoral.', 'jovens', 'participação e voz', 'promessa e entrega', 'funciona', NULL, NULL, '39'), ('D06-TR-136', 'A comparação eleitoral pode funcionar se vier ancorada em fatos vividos: emprego, estudo, preço, acesso, direito, segurança, pandemia, oportunidades. Sem isso, tende a soar como nostalgia ou disputa partidária.', 'jovens', 'participação e voz', 'promessa e entrega', 'funciona', NULL, NULL, '39'), ('D06-TR-142-par', 'Responsabilização é menos um território emocional e mais uma chave de tradução: ganha força quando explica por que o voto para Legislativo, Senado e Congresso afeta salário, escala, direitos, internet, transporte, segurança e programas.', 'jovens', 'participação e voz', 'comunicação e linguagem', 'funciona', NULL, NULL, '40'), ('D06-TR-144-par', 'Quando a comunicação traduz quem aprova, quem bloqueia, quem executa e quem responde, a política deixa de parecer um bloco distante.', 'jovens', 'participação e voz', 'comunicação e linguagem', 'funciona', NULL, NULL, '40'), ('D06-TR-145', 'Esse território é especialmente útil para conectar voto e vida prática: não precisa começar no Senado, precisa começar no problema (escala 6x1, imposto, transporte, internet, Bets, segurança, direitos) e depois mostrar quem decide.', 'jovens', 'participação e voz', 'comunicação e linguagem', 'funciona', NULL, NULL, '40'), ('D06-TR-155-par', 'Proteção do trabalhador, dinheiro no bolso e proteção da família são os territórios de maior lastro espontâneo — já estão na vida dos jovens antes da política aparecer, por isso devem funcionar como portas de entrada principais.', 'jovens', 'participação e voz', 'comunicação e linguagem', 'funciona', NULL, NULL, '42'), ('D06-TR-156-par', 'Brasil Core e Engajamento Cívico têm potencial, mas precisam de prova: Brasil precisa aparecer como cultura vivida e soberania concreta; Engajamento precisa mostrar onde a voz jovem produz efeito.', 'jovens', 'participação e voz', 'comunicação e linguagem', 'funciona', NULL, NULL, '42'), ('D06-TR-158-par', 'Responsabilização e Senado é a principal ponte pedagógica: não mobiliza sozinho, mas ajuda a transformar temas concretos em escolha eleitoral, mostrando quem aprova, quem trava, quem amplia e quem ameaça.', 'jovens', 'participação e voz', 'comunicação e linguagem', 'funciona', NULL, NULL, '42'), ('D06-TR-129', '“Eu acho que os jovens realmente têm poder. Mas nos fizeram acreditar que não.”', 'jovens', 'participação e voz', 'participação política', 'verbatim', NULL, NULL, '38'), ('D06-TR-130', '“Os jovens têm o poder de ir às ruas, pedir melhoria, protestos, criar pautas.”', 'jovens', 'participação e voz', 'participação política', 'verbatim', NULL, NULL, '38'), ('D06-TR-131', '“Hoje basta buscar que todos nós teremos informações.”', 'jovens', 'participação e voz', 'participação política', 'verbatim', NULL, NULL, '38'), ('D06-TR-137', '“Quando me perguntam assim, a primeira coisa que vem é o tamanho da responsabilidade que carrego hoje, que antes não era.”', 'jovens', 'participação e voz', 'promessa e entrega', 'verbatim', NULL, NULL, '39'), ('D06-TR-139', '“Hoje eu tenho mais condições, mais oportunidades de fazer e de acontecer.”', 'jovens', 'participação e voz', 'promessa e entrega', 'verbatim', NULL, NULL, '39'), ('D06-TR-146-par', '“São eles que discutem a pauta. São eles que aprovam e desaprovam. Então a nossa vida passa na mão dos deputados.”', 'jovens', 'participação e voz', 'comunicação e linguagem', 'verbatim', NULL, NULL, '40'), ('D06-TR-148-par', '“As pessoas votam para senador, para deputado, mas não sabem o que fazem. Acham que o importante é só o presidente e o governador.”', 'jovens', 'participação e voz', 'comunicação e linguagem', 'verbatim', NULL, NULL, '40'), ('D06-TR-149-par', '“Seria interessante se ensinassem na escola a atribuição de cada um.”', 'jovens', 'participação e voz', 'comunicação e linguagem', 'verbatim', NULL, NULL, '40'), ('D06-TR-001', 'Entre os jovens deste estudo, há vivência de pressões muito próximas às de adultos das classes C/D, como trabalho, dinheiro, família, segurança e futuro, sem que haja condição plenamente adulta em trajetória, estabilidade, autonomia financeira e confiança política.', 'jovens', NULL, 'condição juvenil', 'perfil', NULL, NULL, '7'), ('D06-TR-004', 'A autopercepção como jovem nem sempre se sustenta, porque já há trabalho, cuidado, ajuda em casa, filhos ou sustentação de planos sob pressão.', 'jovens', NULL, 'condição juvenil', 'perfil', NULL, NULL, '7'), ('D06-TR-005', 'A comunicação precisa reconhecer a vida adulta precoce sem apagar a condição juvenil.', 'jovens', NULL, 'comunicação e linguagem', 'perfil', NULL, NULL, '7'), ('D06-TR-014', 'A condição juvenil não foi perdida: a vida adulta é que chegou cedo demais.', 'jovens', NULL, 'condição juvenil', 'perfil', NULL, NULL, '9'), ('D06-TR-015', 'Entre trabalho, estudo, filhos, casa, segurança e futuro, a juventude aparece menos como fase livre e mais como identidade comprimida por responsabilidades adultas.', 'jovens', NULL, 'condição juvenil', 'perfil', NULL, NULL, '10'), ('D06-TR-024', 'A rotina não é apenas corrida: ela consome o espaço de experimentar a juventude.', 'jovens', NULL, 'jornada de trabalho', 'perfil', NULL, NULL, '11'), ('D06-TR-029', 'Há cobrança de comportamento adulto acompanhada de desqualificação por ser jovem.', 'jovens', NULL, 'etarismo', 'perfil', NULL, NULL, '11'), ('D06-TR-030', 'Existe uma irritação recorrente com estereótipos: jovem irresponsável, geração que não quer trabalhar, gente sem experiência ou sem propriedade para opinar.', 'jovens', NULL, 'etarismo', 'perfil', NULL, NULL, '11'), ('D06-TR-040', 'A maternidade encurta a juventude porque cada plano individual precisa caber dentro da organização da casa.', 'jovens', NULL, 'gênero e trabalho', 'perfil', NULL, NULL, '12'), ('D06-TR-047', 'Há projeção de carreira, casa, estudo, família e estabilidade, mas cada desejo vem acompanhado da pergunta sobre viabilidade: vou conseguir, vou aguentar, vou ter dinheiro, vou ter apoio?', 'jovens', NULL, 'futuro possível', 'perfil', NULL, NULL, '13'), ('D06-TR-048', 'Entre mulheres, o futuro aparece muito conectado à conciliação entre carreira, cuidado e saúde mental, com a pergunta sobre aguentar os limites do trabalho ao lado do desejo de ganhar mais, ter casa e construir família.', 'jovens', NULL, 'saúde mental', 'perfil', NULL, NULL, '13'), ('D06-TR-050', 'Entre homens, o futuro aparece mais associado a identidade, estabilidade e realização profissional, com preocupação constante de não chegar aonde se quer.', 'jovens', NULL, 'juventude e trabalho', 'perfil', NULL, NULL, '13'), ('D06-TR-052', 'Redes sociais, comparação com pares e oscilações no trabalho podem transformar ambição em sensação de atraso.', 'jovens', NULL, 'condição juvenil', 'perfil', NULL, NULL, '13'), ('D06-TR-054', 'Futuro crível é o que mostra caminho, condição e proteção: estudo que leva a oportunidade, trabalho que não adoece, renda que dá previsibilidade e política que reduz o risco de tudo desandar.', 'jovens', NULL, 'futuro possível', 'perfil', NULL, NULL, '13'), ('D06-TR-058', 'O gênero não aparece como tema isolado, mas como camada que atravessa trabalho, segurança, credibilidade, cuidado e futuro.', 'jovens', NULL, 'gênero e trabalho', 'perfil', NULL, NULL, '14'), ('D06-TR-059', 'Além de trabalhar, estudar, cuidar da família e construir futuro, há a exigência de provar competência, calcular riscos e se proteger em situações cotidianas.', 'jovens', NULL, 'gênero e trabalho', 'perfil', NULL, NULL, '14'), ('D06-TR-070', 'Jovem não é uma identidade simples: há desejos, referências e códigos juvenis, enquanto a vida cotidiana já exige estabilidade, renda, cuidado, segurança e responsabilidade.', 'jovens', NULL, 'condição juvenil', 'perfil', NULL, NULL, '15'), ('D06-TR-072', 'Para mulheres, a juventude é atravessada por prova de competência, medo, cuidado e maternidade.', 'jovens', NULL, 'gênero e trabalho', 'perfil', NULL, NULL, '15'), ('D06-TR-152', 'Eles ainda têm muita vida pela frente, mas já carregam responsabilidades de adulto.', 'jovens', NULL, 'condição juvenil', 'perfil', NULL, NULL, '41'), ('D06-TR-153', 'A comunicação pode ativar a tensão entre juventude e responsabilidade precoce: ainda há tempo de mudar o rumo, proteger trajetórias e evitar que essa juventude interrompida vire ciclo para a próxima geração.', 'jovens', NULL, 'condição juvenil', 'perfil', NULL, NULL, '41'), ('D01-TR-042-60', 'O dinheiro aparece como falta ou sonho distante, mas deve ser narrado como retomada de controle.', '60+', 'dinheiro no bolso', 'custo de vida', 'achado', 'indício', NULL, '20'), ('D01-TR-052-60', 'A equação tempo igual a dinheiro pesa no cotidiano.', '60+', 'dinheiro no bolso', 'jornada de trabalho', 'achado', 'indício', NULL, '22'), ('D03-TR-006-60', '5,4% da população obteve renda nos últimos doze meses com alguma atividade online, como vendas, links de afiliados, revendas, visualização remunerada de vídeos ou atuação como ponto de coleta de lojas online.', '60+', 'dinheiro no bolso', 'renda e sustento', 'achado', 'indício', NULL, '15'), ('D03-TR-074-60', 'O combate às desigualdades e privilégios recebe 21,1% de avaliação ótima ou boa e 38,2% ruim ou péssima.', '60+', 'dinheiro no bolso', 'desigualdade', 'achado', 'indício', NULL, '73'), ('D03-TR-075-60', 'Custo de vida, poder de compra e economia é a área com pior avaliação da gestão federal: 16,0% ótima ou boa e 53,7% ruim ou péssima.', '60+', 'dinheiro no bolso', 'custo de vida', 'achado', 'indício', NULL, '73'), ('D03-TR-080-60', 'A isenção do Imposto de Renda para quem ganha até 5 mil reais é conhecida por 72,4%, com avaliação de 68,9% ótima ou boa e 11,4% ruim ou péssima.', '60+', 'dinheiro no bolso', 'impostos', 'achado', 'indício', NULL, '76'), ('D03-TR-083-60', 'O Desenrola, para renegociar dívidas, é conhecido por 62,1%, com avaliação de 67,9% ótima ou boa e 9,7% ruim ou péssima.', '60+', 'dinheiro no bolso', 'endividamento e crédito', 'achado', 'indício', NULL, '76'), ('D03-TR-089-60', 'No Nordeste, o Pé-de-Meia é o programa federal mais conhecido da lista (90,1%), acima da média nacional (81,0%), com avaliação de 69,3% ótima ou boa.', '60+', 'dinheiro no bolso', 'educação', 'achado', 'indício', NULL, '78'), ('D07-TR-001-60', 'Entre os participantes deste estudo, custo de vida, poder de compra e economia é a área de maior peso na formação da avaliação pública de desempenho governamental.', '60+', 'dinheiro no bolso', 'custo de vida', 'achado', 'indício', NULL, '3'), ('D07-TR-018-60', 'Custo de vida concentra o maior impacto isolado sobre a avaliação pública de desempenho, com magnitude cerca de duas vezes a da segunda área da lista.', '60+', 'dinheiro no bolso', 'custo de vida', 'achado', 'indício', NULL, '5'), ('D07-TR-028-60', 'Na Região Sul, o peso de custo de vida na avaliação de desempenho governamental é substancialmente superior ao observado no conjunto do país.', '60+', 'dinheiro no bolso', 'custo de vida', 'achado', 'indício', NULL, '6'), ('D07-TR-045-60', 'Na Região Norte, o peso de custo de vida na avaliação de desempenho governamental é substancialmente superior ao observado no conjunto do país.', '60+', 'dinheiro no bolso', 'custo de vida', 'achado', 'indício', NULL, '10'), ('D09-TR-041', 'A aposentadoria é vivenciada com frustração e são muito poucos os relatos de satisfação com essa condição.', '60+', 'dinheiro no bolso', 'aposentadoria e previdência', 'achado', 'indício', NULL, '9'), ('D09-TR-043', 'A razão essencial da frustração está no valor pago à maioria dos aposentados, exatamente na fase da vida em que gastos com remédios comprometem bastante o orçamento doméstico.', '60+', 'dinheiro no bolso', 'aposentadoria e previdência', 'achado', 'indício', NULL, '9'), ('D09-TR-044', 'Diante da insuficiência do valor recebido, seguir trabalhando é a alternativa adotada por quem ainda consegue.', '60+', 'dinheiro no bolso', 'aposentadoria e previdência', 'achado', 'indício', NULL, '9'), ('D09-TR-045', 'A dependência do auxílio financeiro de filhos e netos impacta negativamente o estado emocional dos idosos, chegando a gerar quadros de depressão.', '60+', 'dinheiro no bolso', 'saúde mental', 'achado', 'indício', NULL, '9'), ('D09-TR-060', 'O valor das aposentadorias está no cerne dos problemas enfrentados pelos idosos.', '60+', 'dinheiro no bolso', 'aposentadoria e previdência', 'achado', 'forte', NULL, '11'), ('D09-TR-061', 'A insuficiência da aposentadoria se relaciona diretamente com a necessidade de amparo na saúde, tema que concentra queixas, reclamações e revolta.', '60+', 'dinheiro no bolso', 'saúde e sus', 'achado', 'indício', NULL, '11'), ('D09-TR-218', 'A recomposição salarial das aposentadorias está entre as principais demandas.', '60+', 'dinheiro no bolso', 'aposentadoria e previdência', 'achado', 'forte', NULL, '45'), ('D09-TR-148-din', 'Falar dos 70+ como um bloco único afasta: há idosos ativos e passivos, e a heterogeneidade é a regra.', '60+', 'dinheiro no bolso', 'envelhecimento e autonomia', 'afasta', NULL, NULL, '4'), ('D09-TR-149-din', 'Associar velhice a passividade, ao idoso "trancado em uma sala na frente de uma televisão", afasta: para muitos, a mobilização física e social é resistência ao papel de descarte.', '60+', 'dinheiro no bolso', 'respeito ao idoso', 'afasta', NULL, NULL, '6'), ('D09-TR-151', 'Apresentar a aposentadoria como descanso merecido e conquista feliz afasta: para a maioria, o valor pago não permite viver dela, e "quando ela chega é uma droga".', '60+', 'dinheiro no bolso', 'aposentadoria e previdência', 'afasta', NULL, NULL, '9'), ('D09-TR-158', 'Aposentadoria e custo de remédios comprometem o orçamento exatamente na fase em que a saúde exige mais gastos; quem não consegue viver da aposentadoria segue trabalhando ou depende de filhos e netos.', '60+', 'dinheiro no bolso', 'aposentadoria e previdência', 'contexto', NULL, NULL, '9'), ('D01-TR-030-60', 'O engajamento nasce de caminho prático, nunca de slogan de superação.', '60+', 'dinheiro no bolso', 'custo de vida', 'funciona', NULL, NULL, '17'), ('D01-TR-046-60', 'Mostrar como um Estado presente pode ajudar no alívio do dia a dia por meio de políticas públicas.', '60+', 'dinheiro no bolso', 'atribuição de políticas públicas', 'funciona', NULL, NULL, '21'), ('D09-TR-042', '"A gente passa a vida sonhando com ela e quando ela chega é uma droga."', '60+', 'dinheiro no bolso', 'aposentadoria e previdência', 'verbatim', NULL, NULL, '9'), ('D09-TR-053', '"Sinceramente, se eu puder trabalhar até os 80, 85, eu vou continuar trabalhando. Por que como é que faz pra viver de aposentadoria?"', '60+', 'dinheiro no bolso', 'aposentadoria e previdência', 'verbatim', NULL, NULL, '10'), ('D09-TR-070', '"Estou esperando até agora nada. Aí eu fiz as duas de pterígio particular e fiz recentemente uma de catarata particular, porque eu não consegui, esperando há não sei quantos anos."', '60+', 'dinheiro no bolso', 'saúde e sus', 'verbatim', NULL, NULL, '12'), ('D09-TR-071', '"Se tem o remédio que o posto não está dando, é R$ 170 e eu tenho que comprar. Isso são três vidros, de R$ 170 cada um. Como fazer com essa aposentadoria vergonhosa que a gente recebe?"', '60+', 'dinheiro no bolso', 'saúde e sus', 'verbatim', NULL, NULL, '12'), ('D09-TR-072', '"Aquilo que a gente recebe é muito pouco, falta até para a gente comprar um remédio. Não tem dignidade com a aposentadoria que nos dão."', '60+', 'dinheiro no bolso', 'aposentadoria e previdência', 'verbatim', NULL, NULL, '13'), ('D09-TR-108', '"Porque a gente vai no mercado, o salário da gente não dá para comprar nada. Então eu perdi a minha vontade de votar."', '60+', 'dinheiro no bolso', 'custo de vida', 'verbatim', NULL, NULL, '17'), ('D01-TR-103-60', 'A vida chegou cedo demais, mas eles não deixaram de ser jovens: a juventude aparece menos como fase livre e mais como identidade comprimida por responsabilidades adultas.', '60+', 'trabalho digno', 'juventude e trabalho', 'achado', 'indício', NULL, '38'), ('D01-TR-104-60', 'A rotina não é só corrida, ela consome o espaço de experimentar a juventude: trabalho, estudo, deslocamento e casa ocupam a maior parte da rotina, e o tempo livre aparece menos como lazer e mais como recuperação física e mental.', '60+', 'trabalho digno', 'jornada de trabalho', 'achado', 'indício', NULL, '38'), ('D03-TR-010-60', 'Carreira, trabalho e sustento é citado por 6,1% como opção mais importante na vida hoje e por 17,9% somando primeira e segunda opções.', '60+', 'trabalho digno', 'renda e sustento', 'achado', 'indício', NULL, '16'), ('D03-TR-081-60', 'O fim da escala 6 por 1 é conhecido por 67,3%, com avaliação de 59,3% ótima ou boa e 18,8% ruim ou péssima.', '60+', 'trabalho digno', 'jornada de trabalho', 'achado', 'indício', NULL, '76'), ('D09-TR-017', 'Parte dos idosos mantém atividades produtivas informais ou bicos para se manter útil e ativo, incluindo produção de bolos e salgados sob encomenda, modelagem e costura, atendimento em farmácias e freelance em hotelaria.', '60+', 'trabalho digno', 'aposentadoria e previdência', 'achado', 'indício', NULL, '6'), ('D09-TR-219', 'Políticas de inclusão de idosos ativos no mercado de trabalho e combate ao etarismo corporativo estão entre as principais demandas.', '60+', 'trabalho digno', 'etarismo', 'achado', 'forte', NULL, '45'), ('D09-TR-148-tra', 'Falar dos 70+ como um bloco único afasta: há idosos ativos e passivos, e a heterogeneidade é a regra.', '60+', 'trabalho digno', 'envelhecimento e autonomia', 'afasta', NULL, NULL, '4'), ('D09-TR-149-tra', 'Associar velhice a passividade, ao idoso "trancado em uma sala na frente de uma televisão", afasta: para muitos, a mobilização física e social é resistência ao papel de descarte.', '60+', 'trabalho digno', 'respeito ao idoso', 'afasta', NULL, NULL, '6'), ('D09-TR-154', 'Falar de aposentadoria ou benefícios sem reconhecer a vida de trabalho e sustento da família afasta: o que falta, para este público, é respeito e reconhecimento.', '60+', 'trabalho digno', 'reconhecimento do trabalho', 'afasta', NULL, NULL, '12'), ('D09-TR-159', 'Idosos ativos seguem em atividades produtivas informais e bicos para se manterem úteis; outros querem trabalhar e não encontram quem contrate pela idade.', '60+', 'trabalho digno', 'etarismo', 'contexto', NULL, NULL, '6'), ('D01-TR-144-60-tra', 'Quando a pergunta sobre o Senado é reformulada de forma concreta, associando-o a salário, escala de trabalho e direitos, o tom muda de indiferença para indignação.', '60+', 'trabalho digno', 'funcionamento do legislativo', 'funciona', NULL, NULL, '55'), ('D09-TR-225', 'Reconhecer explicitamente a contribuição de quem dedicou a vida ao trabalho e ao sustento da família aproxima: para este público, o que falta à sociedade é respeito e reconhecimento por essa trajetória.', '60+', 'trabalho digno', 'reconhecimento do trabalho', 'funciona', NULL, NULL, '12'), ('D09-TR-056', '"Queria ter um emprego, mas quem dá emprego pra uma pessoa da minha idade?"', '60+', 'trabalho digno', 'etarismo', 'verbatim', NULL, NULL, '10'), ('D09-TR-066', '"Eu sou aposentado, a minha esposa é de casa, então ela nunca trabalhou registrada. Ela já tá com 70 anos, ela não tem direito a receber nada. É errado! Ela trabalhou a vida toda em casa."', '60+', 'trabalho digno', 'aposentadoria e previdência', 'verbatim', NULL, NULL, '12'), ('D01-TR-028-60', 'As políticas públicas fazem parte do dia a dia sem serem necessariamente lembradas de forma espontânea; a percepção dos benefícios é muitas vezes escassa ou pouco associada a um governo ou período específico.', '60+', 'família e cuidado', 'atribuição de políticas públicas', 'achado', 'indício', NULL, '17'), ('D01-TR-041-60', 'A falta de rede de apoio é apontada como marca comum dos perfis de mulheres.', '60+', 'família e cuidado', 'rede de apoio', 'achado', 'indício', NULL, '18'), ('D01-TR-053-60', 'Segurança pública é problema concreto na vida da mulher.', '60+', 'família e cuidado', 'segurança pública', 'achado', 'indício', NULL, '23'), ('D01-TR-055-60', 'A família e cuidado é entendida como conjunto multifacetado: segurança física (ruas, escola, creche), segurança digital (crianças e redes sociais), acesso a saúde e educação, e estabilidade financeira.', '60+', 'família e cuidado', 'segurança pública', 'achado', 'indício', NULL, '24'), ('D01-TR-056-60', 'Entre os participantes deste estudo, o medo da violência é universal, visceral e transversal, mas nenhuma resposta institucional convence.', '60+', 'família e cuidado', 'segurança pública', 'achado', 'forte', NULL, '25'), ('D01-TR-058-60', 'Medida protetiva e Delegacia da Mulher são termos conhecidos, mas a desconfiança na eficácia real permanece.', '60+', 'família e cuidado', 'violência contra a mulher', 'achado', 'indício', NULL, '25'), ('D03-TR-007-60', 'Família é a opção mais citada como mais importante na vida hoje: 57,2% em primeira opção e 80,3% somando primeira e segunda opções.', '60+', 'família e cuidado', 'família e maternidade', 'achado', 'indício', NULL, '16'), ('D03-TR-008-60', 'Saúde e bem-estar é a segunda opção mais citada como mais importante na vida hoje: 22,5% em primeira opção e 55,9% somando primeira e segunda opções.', '60+', 'família e cuidado', 'saúde e sus', 'achado', 'indício', NULL, '16'), ('D03-TR-009-60', 'Fé e religiosidade aparece como terceira opção mais importante na vida hoje: 11,2% em primeira opção e 30,4% somando primeira e segunda opções.', '60+', 'família e cuidado', 'fé e religiosidade', 'achado', 'indício', NULL, '16'), ('D03-TR-011-60', 'Tempo livre e viagens é citado por 1,4% como opção mais importante na vida hoje e por 5,7% somando primeira e segunda opções.', '60+', 'família e cuidado', 'cultura e lazer', 'achado', 'indício', NULL, '16'), ('D03-TR-012-60', 'Esporte, cultura e lazer é citado por 1,3% como opção mais importante na vida hoje e por 4,6% somando primeira e segunda opções.', '60+', 'família e cuidado', 'cultura e lazer', 'achado', 'indício', NULL, '16'), ('D03-TR-069-60', 'A educação pública na gestão federal recebe 27,7% de avaliação ótima ou boa e 33,0% ruim ou péssima.', '60+', 'família e cuidado', 'educação', 'achado', 'indício', NULL, '73'), ('D03-TR-072-60', 'A saúde pública na gestão federal recebe 21,5% de avaliação ótima ou boa e 44,5% ruim ou péssima, com apenas 1,4% sem saber avaliar.', '60+', 'família e cuidado', 'saúde e sus', 'achado', 'indício', NULL, '73'), ('D03-TR-073-60', 'A segurança pública na gestão federal recebe 21,3% de avaliação ótima ou boa e 40,2% ruim ou péssima.', '60+', 'família e cuidado', 'segurança pública', 'achado', 'indício', NULL, '73'), ('D03-TR-076-60